WITH cleaned AS (SELECT id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, COALESCE(level, 'N/A') AS level_filled, COALESCE(level, 'UNKNOWN') AS level_clean FROM employees WHERE hire_date >= DATE '2023-03-14') SELECT e.id, e.email, e.dept_id, e.manager_id, e.level_filled, e.level_clean, p.job_title AS employee_job_title, p.level FROM cleaned e LEFT JOIN employees p ON e.manager_id <=> p.id;
